import{_ as a,c as t,o as s,ag as n}from"./chunks/framework.Vyheyqg9.js";const u=JSON.parse('{"title":"Account, development tools and cost awareness","description":"","frontmatter":{},"headers":[],"relativePath":"aws/account-and-tools.md","filePath":"aws/account-and-tools.md"}'),r={name:"aws/account-and-tools.md"};function i(o,e,d,l,c,h){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="account-development-tools-and-cost-awareness" tabindex="-1">Account, development tools and cost awareness <a class="header-anchor" href="#account-development-tools-and-cost-awareness" aria-label="Permalink to “Account, development tools and cost awareness”">​</a></h1><p>An AWS account owns resources and their billing. Before deploying anything, understand which identity, account and Region your tools will use.</p><h2 id="account-creation-and-everyday-access" tabindex="-1"><span class="hub-section-number">1 </span>Account creation and everyday access <a class="header-anchor" href="#account-creation-and-everyday-access" aria-label="Permalink to “1 Account creation and everyday access”">​</a></h2><p>Use the <a href="https://repost.aws/knowledge-center/create-and-activate-aws-account" target="_blank" rel="noreferrer">official account creation guidance</a>. Registration involves email verification, contact and payment details, and identity verification; exact screens and available plans change. Read the current terms rather than reproduce an older screenshot&#39;s choices blindly.</p><p>Protect the root identity with MFA and use it only for tasks that require it. Prefer federated everyday access through IAM Identity Center and temporary role credentials. The supplied course&#39;s long-lived administrator access keys explain a historical setup, but should not be the default for new learning notes. AWS recommends temporary credentials for people and workloads. <a href="https://docs.aws.amazon.com/IAM/latest/UserGuide/best-practices.html" target="_blank" rel="noreferrer">IAM security guidance</a>.</p><p>Keep credentials out of source code, screenshots, frontend bundles and committed environment files. An example credential in a tutorial is not a value to reuse.</p><h2 id="console-cli-sdk-and-infrastructure-as-code" tabindex="-1"><span class="hub-section-number">2 </span>Console, CLI, SDK and infrastructure as code <a class="header-anchor" href="#console-cli-sdk-and-infrastructure-as-code" aria-label="Permalink to “2 Console, CLI, SDK and infrastructure as code”">​</a></h2><table tabindex="0"><thead><tr><th>Interface</th><th>Useful for</th><th>Important boundary</th></tr></thead><tbody><tr><td>Console</td><td>Inspect resources and understand configuration</td><td>Manual changes are easy to forget</td></tr><tr><td>CLI</td><td>Repeatable commands and diagnostics</td><td>Selected profile and Region determine the target</td></tr><tr><td>SDK</td><td>Application code calling AWS APIs</td><td>Calls use the application&#39;s credentials and permissions</td></tr><tr><td>CDK / CloudFormation</td><td>Declare infrastructure in versioned files</td><td>Deployment can create, replace or delete resources</td></tr></tbody></table><p>A named profile separates account/role settings. For an Identity Center profile, a typical authentication and identity check is:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">aws</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> configure</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sso</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> learning</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">aws</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sso</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> learning</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">aws</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get-caller-identity</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> learning</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">aws</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> configure</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> region</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> learning</span></span></code></pre></div><p>These commands do not deploy infrastructure. The account ID and role in the identity response help detect an accidental production target. A Region may be supplied through a profile, environment or an individual command, so inspect overrides when results differ from expectations.</p><p>SDK clients use a credential provider chain. In Lambda, use the execution role; locally, use your configured development identity. Never embed secret access keys in code merely to make the SDK work.</p><h2 id="budgets-and-current-pricing" tabindex="-1"><span class="hub-section-number">3 </span>Budgets and current pricing <a class="header-anchor" href="#budgets-and-current-pricing" aria-label="Permalink to “3 Budgets and current pricing”">​</a></h2><p>Use <a href="https://docs.aws.amazon.com/cost-management/latest/userguide/budgets-managing-costs.html" target="_blank" rel="noreferrer">AWS Budgets</a>, <a href="https://aws.amazon.com/aws-cost-management/aws-cost-explorer/" target="_blank" rel="noreferrer">Cost Explorer</a> and the <a href="https://calculator.aws/" target="_blank" rel="noreferrer">Pricing Calculator</a> for different purposes: alerts, spending analysis and estimates. Check the <a href="https://aws.amazon.com/free/" target="_blank" rel="noreferrer">current Free Tier</a> and your account&#39;s eligibility before using a service.</p><p>Budget information and notifications can lag usage. An alert does not undo charges or automatically stop every resource. Automated budget actions are a separate configuration with their own scope.</p><p>Resource tags such as <code>Project=learning-store</code> and <code>Environment=learning</code> make ownership and cost attribution easier. Tags do not themselves restrict access or guarantee that every resource appears in one inventory.</p><h2 id="resource-lifetime" tabindex="-1"><span class="hub-section-number">4 </span>Resource lifetime <a class="header-anchor" href="#resource-lifetime" aria-label="Permalink to “4 Resource lifetime”">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>What may remain</th></tr></thead><tbody><tr><td>Stop an EC2 instance</td><td>EBS volumes, snapshots, allocated addresses</td></tr><tr><td>Delete an application stack</td><td>Retained resources, snapshots, resources made outside the stack</td></tr><tr><td>Delete a versioned S3 object&#39;s current version</td><td>Previous versions and possibly a delete marker</td></tr><tr><td>Remove a Lambda</td><td>Log groups and separately owned integrations</td></tr><tr><td>Delete a database</td><td>Retained backups or a final snapshot</td></tr></tbody></table><p>Use <a href="./delivery-and-operations.html">delivery and operations</a> for cleanup order. Cleanup is part of resource ownership, and should be planned when a resource is created.</p><p>Next: <a href="./iam-and-security.html">IAM and security</a>.</p>`,20)])])}const g=a(r,[["render",i]]);export{u as __pageData,g as default};
